{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Carebastine, which contains the same 4-(2-carboxypropan-2-yl)phenyl acid as the query, is a zwitterion at physiological pH and does not cross the BBB; this directly supports fail for the query's acid-containing zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Fexofenadine, another zwitterionic antihistamine with the same C(CH3)2COOH-phenyl acid and a basic piperidine, is unable to cross the BBB, supporting that the query's acid/base zwitterion will lack meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Oral carebastine required an ID50 of 83.9 mg/kg to inhibit central H1 binding, indicating very poor brain penetration; the query shares the same acid-bearing side chain and basic center.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The ethoxyethyl-benzimidazole analogue emedastine showed a brain/plasma radioactivity ratio of 1/17, demonstrating that the query's core can be associated with very low CNS distribution when combined with polar/basic features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The closest ethoxyethyl-benzimidazole-piperidine analogue (Morgan 0.56) had B/Pb 0.8 after iv dosing, showing the core without the acid does not guarantee high brain exposure; adding the ionizable acid would further reduce access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A close ethoxyethyl-benzimidazole-piperidine analogue with a lipophilic N-tetrahydropyranyl substituent had B/Pb 2.6, showing the core can be brain-penetrant when the N-substituent is lipophilic; however, the query's N-substituent is a zwitterionic acid-bearing phenethyl, so this positive result does not transfer.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "A benzimidazole-piperidine analogue without the acid had B/Pb 2.7, but lacks the query's ionizable carboxylic acid, so its positive brain penetration does not override the zwitterion liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a zwitterionic benzimidazole-piperidine bearing the same 4-(2-carboxypropan-2-yl)phenyl acid as carebastine and fexofenadine, both of which are experimentally impermeable to the BBB. Direct ethoxyethyl-benzimidazole analogues are mixed (B/Pb 0.8–2.6) but lack the acid; emedastine with the same core shows very low brain/plasma distribution. The acid/base zwitterion is the dominant liability, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain/plasma/CSF measurement for the exact query molecule.",
    "No efflux transporter (P-gp/BCRP) or active uptake transporter data for the query.",
    "Possible active uptake mechanisms cannot be excluded without direct transporter studies."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C23", "C17", "C19", "C14", "C20", "C18", "C12"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "carebastine/fexofenadine zwitterionic acid antihistamines"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C13", "C21", "C15", "C22"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "ethoxyethyl-benzimidazole core analogues"
    }
  ],
  "revision_action": "strengthen"
}

